WITH deduped AS (SELECT * FROM products QUALIFY ROW_NUMBER() OVER (PARTITION BY brand ORDER BY launch_date, id) = 1) SELECT CASE WHEN price >= 1260 THEN 'LARGE' ELSE 'SMALL' END AS price_tier, ROUND(SUM(stock_qty) / NULLIF(COUNT(CASE WHEN brand = 'Stark' THEN 1 END), 0), 2) AS stock_qty_per_stark, ROUND(AVG(stock_qty), 2) AS avg_stock_qty, COUNT(DISTINCT brand) AS distinct_brands, ROUND(AVG(price), 2) AS avg_price, COUNT(*) FILTER (WHERE category = 'Grocery') AS grocery_rows, MAX(price) AS max_price FROM deduped GROUP BY price_tier ORDER BY max_price DESC;
